library(irace)
EXPECTED_DIR <- "irace_ils_without_PR"
if (basename(normalizePath(getwd(), winslash="/", mustWork=TRUE)) != EXPECTED_DIR) stop("Set the RStudio working directory to ",EXPECTED_DIR,".")
required <- c("scenario.txt","parameters.txt","initial_configuration.txt","instances_calibration.txt","manifest_calibration.csv","target_runner_ils.py","preflight_ok.txt")
missing <- required[!file.exists(required)]
if (length(missing)>0) stop("Missing file(s): ",paste(missing,collapse=", "))
lines <- readLines("instances_calibration.txt",warn=FALSE); lines <- lines[nzchar(trimws(lines))]
if (length(lines)!=72) stop("instances_calibration.txt must contain exactly 72 instances; found ",length(lines),".")
old <- c("irace_ils_calibration_fi_bi_4groups.Rdata","run_level_results.csv","final_elites.csv","final_elites_with_strategy.csv","all_configurations.csv","experiments_matrix.csv","instance_algorithm_seed_pairs.csv","calibration_metadata.txt","irace_summary.txt")
existing <- old[file.exists(old)]
if (length(existing)>0) stop("Previous official output(s) already exist: ",paste(existing,collapse=", "))
PROJECT_ROOT <- normalizePath(file.path(getwd(), "..", ".."), winslash="/", mustWork=TRUE)
INSTANCE_DIR <- file.path(PROJECT_ROOT, "instances", "instances_seed_11_12_13_N60_100_200_400")
if (!file.exists(file.path(PROJECT_ROOT, "src", "mnl_ils.py"))) stop("Missing src/mnl_ils.py")
instance_names <- basename(gsub("\\\\", "/", trimws(lines)))
if (anyDuplicated(instance_names)) stop("Duplicate calibration instances")
if (any(!file.exists(file.path(INSTANCE_DIR, instance_names)))) stop("Missing calibration NPZ file(s)")
scenario <- readScenario("scenario.txt")
cat("\n========================================\nOFFICIAL ILS CALIBRATION — BI + FI\nFOUR SIZE GROUPS: N=60,100,200,400\n========================================\n")
cat("Instances: 72\nBlocks: 18 x 4\nParameters: 13\nfirstImprovement: 0=BI, 1=FI\nmaxExperiments =",scenario$maxExperiments,"\n")
start_time <- Sys.time(); timing <- system.time({ final_elites <- irace(scenario=scenario) }); end_time <- Sys.time()
cat("\n========================================\nFINAL ELITE CONFIGURATION(S)\n========================================\n"); print(final_elites)
write.csv(final_elites,"final_elites.csv",row.names=FALSE)
elite_out <- final_elites
if ("firstImprovement" %in% names(elite_out)) elite_out$strategy <- ifelse(as.character(elite_out$firstImprovement) %in% c("1","TRUE","true"),"FI","BI")
write.csv(elite_out,"final_elites_with_strategy.csv",row.names=FALSE)
logfile <- "irace_ils_calibration_fi_bi_4groups.Rdata"
if (!file.exists(logfile)) stop("Expected ",logfile," was not created.")
load(logfile); if (!exists("iraceResults")) stop("iraceResults not found in Rdata.")
write.csv(iraceResults$allConfigurations,"all_configurations.csv",row.names=FALSE)
write.csv(as.data.frame(iraceResults$experiments),"experiments_matrix.csv",row.names=TRUE)
pairs <- tryCatch(get_instanceID_seed_pairs(iraceResults),error=function(e) NULL)
if (!is.null(pairs)) write.csv(as.data.frame(pairs),"instance_algorithm_seed_pairs.csv",row.names=FALSE)
summary_txt <- tryCatch(capture.output(irace_summarise(iraceResults)),error=function(e) paste("irace_summarise unavailable:",conditionMessage(e)))
writeLines(summary_txt,"irace_summary.txt")
n_rows <- NA_integer_; if (file.exists("run_level_results.csv")) n_rows <- max(0L,length(readLines("run_level_results.csv",warn=FALSE))-1L)
metadata <- c(paste("Start:",start_time),paste("End:",end_time),paste("Wall_clock_seconds:",unname(timing[["elapsed"]])),paste("irace_version:",as.character(packageVersion("irace"))),paste("R_version:",R.version.string),paste("irace_seed:",scenario$seed),paste("maxExperiments:",scenario$maxExperiments),paste("blockSize:",scenario$blockSize),paste("testType:",scenario$testType),paste("confidence:",scenario$confidence),paste("run_level_rows:",n_rows),"design_instances: 72","design_blocks: 18 x 4","N_groups: 60,100,200,400","p_low: 3,5,10,20","p_high: 6,10,20,30","alpha: 0.5,1.0,2.0","instance_seeds: 11,12,13","firstImprovement: 0=BI, 1=FI","", "SESSION INFO",capture.output(sessionInfo()))
writeLines(metadata,"calibration_metadata.txt")
cat("\nOFFICIAL CALIBRATION FINISHED\n")
